using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CoastalGroundStones{
const string Dir="Assets/Scenes/Oasis/CoastalTerrain/Crags";static CoastalGroundStones(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("CoastalGroundStones.request")||EditorApplication.isCompiling)return;File.Delete("CoastalGroundStones.request");Run();}
static void Run(){try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Coastal Rocky Terrain");var terrain=root.GetComponentInChildren<Terrain>();var old=root.transform.Find("Near foothill loose stones");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var group=new GameObject("Near foothill loose stones");group.transform.SetParent(root.transform,false);var soilPath=Dir+"/Mountain Soil Stones.png";var importer=(TextureImporter)AssetImporter.GetAtPath(soilPath);importer.wrapMode=TextureWrapMode.Repeat;importer.mipmapEnabled=true;importer.streamingMipmaps=true;importer.maxTextureSize=2048;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=2;foreach(string platform in new[]{"Android","iPhone"})importer.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name=platform,overridden=true,maxTextureSize=2048,format=TextureImporterFormat.ASTC_6x6});importer.SaveAndReimport();var soil=terrain.terrainData.terrainLayers[2];soil.diffuseTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(soilPath);EditorUtility.SetDirty(soil);terrain.terrainData.SetBaseMapDirty();terrain.Flush();var source=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scenes/Oasis/CoastalTerrain/Details/Boulder 1 distant.asset");var material=AssetDatabase.LoadAssetAtPath<Material>(Dir+"/Shared Large Granite Faces.mat");var line=File.ReadAllLines("FinalEnvironmentRoadReview/CoastalSnappedEdge.txt").Select(s=>{var v=s.Trim('(',')').Split(',');return new Vector2(float.Parse(v[0],System.Globalization.CultureInfo.InvariantCulture),float.Parse(v[1],System.Globalization.CultureInfo.InvariantCulture));}).ToArray();var rng=new System.Random(946);var batches=new Dictionary<Vector2Int,List<CombineInstance>>();int count=0;var pos=terrain.transform.position;var size=terrain.terrainData.size;for(float z=pos.z+2;z<pos.z+size.z-2;z+=3.4f)for(float x=pos.x+2;x<pos.x+size.x-2;x+=3.4f){float wx=x+(float)rng.NextDouble()*2-1,wz=z+(float)rng.NextDouble()*2-1;float u=(wx-pos.x)/size.x,v=(wz-pos.z)/size.z;if(terrain.terrainData.IsHole(Mathf.FloorToInt(u*512),Mathf.FloorToInt(v*512)))continue;var p=new Vector2(wx,wz);float d=float.MaxValue;for(int i=0;i<line.Length-1;i++){var e=line[i+1]-line[i];d=Mathf.Min(d,Vector2.Distance(p,line[i]+e*Mathf.Clamp01(Vector2.Dot(p-line[i],e)/e.sqrMagnitude)));}if(d<4||d>20||rng.NextDouble()>.55)continue;float scale=.15f+(float)rng.NextDouble()*.42f;var matrix=Matrix4x4.TRS(new Vector3(wx,terrain.SampleHeight(new Vector3(wx,0,wz))-scale*.2f,wz),Quaternion.Euler((float)rng.NextDouble()*50,(float)rng.NextDouble()*360,(float)rng.NextDouble()*35),new Vector3(scale,scale*.7f,scale*1.1f));var key=new Vector2Int(Mathf.FloorToInt(wx/40),Mathf.FloorToInt(wz/40));if(!batches.TryGetValue(key,out var list)){list=new List<CombineInstance>();batches.Add(key,list);}list.Add(new CombineInstance{mesh=source,transform=matrix});count++;}
foreach(var item in batches){var mesh=new Mesh{name="Loose mountain stones "+item.Key};mesh.CombineMeshes(item.Value.ToArray(),true,true);string path=Dir+"/Ground Stones "+item.Key.x+" "+item.Key.y+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing){existing.Clear();existing.vertices=mesh.vertices;existing.triangles=mesh.triangles;existing.uv=mesh.uv;existing.normals=mesh.normals;existing.RecalculateBounds();UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;EditorUtility.SetDirty(mesh);}else AssetDatabase.CreateAsset(mesh,path);var go=new GameObject(mesh.name);go.transform.SetParent(group.transform,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=go.AddComponent<MeshRenderer>();renderer.sharedMaterial=material;renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;var lod=go.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.15f,new[]{renderer})});lod.RecalculateBounds();}
PrefabUtility.SaveAsPrefabAssetAndConnect(root,"Assets/Scenes/Oasis/CoastalTerrain/Coastal Rocky Terrain.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,new Vector3(812,32,190),new Vector3(852,48,210),"Mountain-Surface-Final-Closeup"});capture.Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Mountain-Surface-Final-Road-Level"});File.WriteAllText("FinalEnvironmentRoadReview/CoastalGroundStonesReport.txt","SUCCESS close-distance stones="+count+"; sectors="+batches.Count+"; shared existing rock material; no new textures; no colliders; distance culled; terrain footprint and roadside clearance retained.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CoastalGroundStonesReport.txt","FAILED "+e);Debug.LogException(e);}}}
